#include "stdafx.h"#include "HcdElementBase.h"#include <HcdMemoryService.h>#include <HcdDataTypes_.h>#include <float.h>struct SAI_P{#include "PrivateVars/AI.h"};class KAI : public KHcdElementBase          , protected SAI_P{  W_AI *m_pHardware;  tAnalog32 m_Scale;public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void OnFilledProjectSettings();  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _AI("AI", KAI::Create);IHcdElement *KAI::Create(){  return new KAI;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KAI, 14 )void KAI::InitParm(){#include "PrivateVars/AI.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KAI::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;  m_pHardware = (W_AI*)KMemoryServiceHCD::Instance().IoCreateObj( szName, W_AI::TypeID, domain );  m_pSharedObject = (BYTE*)m_pHardware;  m_pSharedVarsInfo = new SVarInfo;  AddSharedField( "RAW", NULL, offsetof(W_AI, W_AI::RAW), ehtAnalog32, sizeof(tAnalog32), 1 );  m_pHardware->RAW = FLT_MAX;  m_Scale = 1.f;}void KAI::OnFilledProjectSettings(){  m_Scale = ( HI - LO ) / 100.f;}void KAI::StepCalc( SStepCalcParams &params ){  if( DIS )  {    OUTD0 = DisabledChannelOutput;    return;  }  if( FLT_MAX==m_pHardware->RAW )    FAIL = 1;  else  {    //OUTD0 = m_pHardware->RAW * m_Scale + Bias;    OUTD0 = m_pHardware->RAW;    FAIL = 0;  }}